// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testRegression_property() public {
        // First call seedMarket to initialize the market and set initialized = true in reference
        // In the buggy version, seedMarket sets initialized = false, so we need to call DrugDealer after
        // seedMarket to see the difference in the initialized state.
        // We need some ETH to call seedMarket since it's payable, but we don't need much.
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 0}(100);

        // Now call DrugDealer which is supposed to change ceoAddress (but does not affect initialized directly)
        // However, reference has initialized = true after seedMarket, bug has initialized = false
        vm.prank(c.ceoAddress());
        c.DrugDealer();

        // Check the value of initialized
        // In reference, initialized should be true; in bug, initialized should be false
        assertTrue(c.initialized() == true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // CEO is 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26, call DrugDealer() first
        vm.prank(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        c.DrugDealer();
        // Now ceoAddress is msg.sender in reference, or 0x0 in bug
        // Try with a different address (not 0x0) — reference should succeed, bug should revert
        address other = address(0x123);
        vm.prank(other);
        bool ok;
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: ceoAddress was set to 0x85... so other (0x123) != ceoAddress, revert? Wait: after first call, ceoAddress becomes 0x85... in reference, so other != ceoAddress, revert. Actually we need a sequence where reference succeeds and bug fails.
        // Let's think: CEO calls first, reference sets ceoAddress to CEO. Then another address calls — both revert because caller != ceoAddress. That's same behavior.
        // Instead: CEO calls once, then reference's ceoAddress is CEO, bug's is 0x0. Call with CEO again: reference succeeds, bug reverts because CEO != 0x0.
        vm.prank(0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        try c.DrugDealer() {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference: ceoAddress = CEO (0x85...), so same caller passes; ok = true
        // In bug: ceoAddress = 0x0, so caller (0x85...) != 0x0, revert; ok = false
        assertTrue(ok, "Reference should succeed on second call by CEO");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Seed the market with some drugs to make initialized true
        c.seedMarket(100);
        // Create two users: Alice and Bob
        address alice = address(0x1111);
        address bob = address(0x2222);
        // Give Alice some ether to buy drugs
        vm.deal(alice, 1 ether);
        // Alice buys drugs to have claimedDrugs for later
        vm.prank(alice);
        c.buyDrugs{value: 0.1 ether}();
        // Bob calls getFreeKilo() (warp to set block.timestamp)
        vm.warp(1000);
        vm.prank(bob);
        c.getFreeKilo();
        // Now Alice calls collectDrugs with bob as ref, which reads bob's lastCollect via getDrugsSinceLastCollect
        vm.prank(alice);
        c.collectDrugs(bob);
        // At this point, in reference, bob's lastCollect = 1000 (set by getFreeKilo), so getDrugsSinceLastCollect(bob) = min(86400, 1000-1000)*Kilos[bob] = 0
        // In mutant, bob's lastCollect = 0 (never set), so getDrugsSinceLastCollect(bob) = min(86400, 1000-0)*Kilos[bob] = 1000 * 300 = 300000
        // Therefore getMyDrugs() for bob differs (claimedDrugs maybe 0 initially)
        uint256 refValue = c.getMyDrugs();
        // We assert that the result is exactly as in reference (0, because lastCollect was set)
        assertTrue(refValue == 0, "In reference, bob's getMyDrugs should be 0; mutant gives non-zero");
    }
}

