pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set block.timestamp to a known value
        vm.warp(1000);

        // Seed the market to initialize the contract
        c.seedMarket(1000);

        // Actor to call getFreeKilo
        address alice = address(0x123);
        vm.deal(alice, 1 ether);

        // Alice gets free kilo (reference sets lastCollect to 1000, mutant does not)
        vm.prank(alice);
        c.getFreeKilo();

        // Advance time by 100 seconds (less than DRUGS_TO_PRODUCE_1KILO = 86400)
        vm.warp(1100);

        // Bob as referrer
        address bob = address(0x456);

        // Alice calls collectDrugs with bob as ref
        vm.prank(alice);
        c.collectDrugs(bob);

        // In reference: lastCollect[alice] = 1000, secondsPassed = 100, drugsSinceLastCollect = 100 * 300 = 30000, claimedDrugs[alice]=0 before, so drugsUsed = 30000
        // newKilo = 30000/86400 = 0, claimedDrugs[alice] set to 0, drugsUsed/5 = 6000 added to bob
        // In mutant: lastCollect[alice] stays 0, secondsPassed = min(86400, 1100-0) = 1100, drugsSinceLastCollect = 1100 * 300 = 330000, drugsUsed = 330000
        // newKilo = 330000/86400 = 3, drugsUsed/5 = 66000 added to bob
        // So bob's claimedDrugs differs

        uint256 bobClaimed = c.claimedDrugs(bob);

        // Reference gives bob 6000, mutant gives 66000
        // Assert it equals the reference value (6000)
        assertTrue(bobClaimed == 6000, "Bob's claimedDrugs should be 6000 in correct contract");
    }
}

