pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Seed the market to initialize the contract
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(1000);

        // Step 2: Give free kilos to two users so they can produce drugs
        address user1 = address(0x123);
        address user2 = address(0x456);
        vm.prank(user1);
        c.getFreeKilo();
        vm.prank(user2);
        c.getFreeKilo();

        // Step 3: Warp forward so that drugs accumulate
        vm.warp(block.timestamp + 86400); // 1 day = 1 kilo of drugs

        // Step 4: user1 calls collectDrugs with user2 as referrer
        vm.prank(user1);
        c.collectDrugs(user2);

        // Step 5: Check the referrer's (user2) claimedDrugs
        // In the correct contract, referrals[user1] is set to user2, so user2 gets a referral bonus.
        // In the buggy contract, referrals[user1] remains address(0), so user2 gets nothing.
        uint256 referrerClaimed = c.claimedDrugs(user2);

        // The correct contract gives 1/5 of user1's produced drugs (which is 1 kilo = 86400) = 17280
        // The buggy contract gives 0
        assertTrue(referrerClaimed > 0, "Referrer should have claimed drugs in correct version");
    }
}

