pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address attacker = address(0x1234);
        address expectedCEO = c.ceoAddress();

        vm.prank(attacker);
        (bool success, ) = address(c).call(abi.encodeWithSignature("DrugDealer()"));

        // In reference contract, the call reverts (success=false) and ceoAddress stays same.
        // In buggy contract, the call succeeds (success=true) and ceoAddress changes to attacker.
        bool ceoChanged = (c.ceoAddress() != expectedCEO);

        // The reference contract: success=false AND ceoChanged=false
        // The buggy contract: success=true AND ceoChanged=true
        // So we assert: NOT (success AND ceoChanged) which reference satisfies, bug breaks
        assertTrue(!(success && ceoChanged));
    }
}

