        // In bug, bob's claimedDrugs stays 0 because referral was set to address(0)
        uint256 bobClaimed = c.claimedDrugs(bob);

        // Bob's claimedDrugs should be non-zero in the reference, but zero in the bug
        assertTrue(bobClaimed > 0);
    }
