// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // seed the market with 1 drug so initialized = true and marketDrugs = 1
        c.seedMarket(1);

        // deal ether to the test contract (this) and call buyDrugs with 1 ether
        vm.deal(address(this), 1 ether);
        c.buyDrugs{value: 1 ether}();

        // get the claimedDrugs for this caller
        uint256 claimed = c.claimedDrugs(address(this));

        // The reference (correct) subtracts devFee: drugsBought = raw - 4% of raw = raw * 96 / 100
        // The buggy adds devFee: drugsBought = raw + 4% of raw = raw * 104 / 100
        // We assert that claimed < (1 ether * 100 / 100) i.e. less than the raw amount to catch the bug
