        // So contract balance decreases by exactly drugValue (since it's sent out)
        // In mutant: drugValue is doubled, so more eth is sent out, balance decreases more
        uint256 balanceAfter = address(c).balance;

        // For reference: contract balance decreases by some amount, for mutant it decreases by more
        // We want an assertion that holds for reference but fails for mutant.
