    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(86400);
        uint256 result = c.calculateDrugSell(86400);
        assertTrue(result > 0);
    }
}
